  public Grid Root=new Grid();public Viewport3D Viewport=new Viewport3D();public OrbitCamera Camera=new OrbitCamera();public List<SceneNode> Nodes=new List<SceneNode>();public HashSet<string> Hidden=new HashSet<string>();public event Action Loaded;public event Action<string> Picked;public bool Ready,Exploded,HideHousing,ShowMarkers=true;public int Axis=-1;public double Coordinate;public bool Positive;public double Phase;public int MeshBuildCount;public double BuildMilliseconds,LastPoseMilliseconds;public int TriangleCount;public string Error;public Result Result;
  readonly BeltMotion belt=new BeltMotion();readonly Model3DGroup models=new Model3DGroup();readonly ModelVisual3D visual=new ModelVisual3D();readonly Dictionary<int,Material> materials=new Dictionary<int,Material>();readonly TextBlock status=new TextBlock(),help=new TextBlock();CancellationTokenSource cancellation;int generation;bool disposed;Point previous,start;bool dragging,panning;bool fitPending;string selected;static readonly object buildLock=new object();
  public WpfScene(){
   Root.Background=new SolidColorBrush(Color.FromRgb(246,249,252));Root.Focusable=true;Viewport.Camera=Camera.Camera;Viewport.IsHitTestVisible=false;Root.Children.Add(Viewport);visual.Content=models;Viewport.Children.Add(visual);status.Foreground=Brushes.SlateGray;status.Margin=new Thickness(12);status.IsHitTestVisible=false;status.VerticalAlignment=VerticalAlignment.Top;Root.Children.Add(status);help.Text="ЛКМ — вращение · СКМ / Shift+ЛКМ — сдвиг · колесо — масштаб · F — вписать";help.Foreground=Brushes.SlateGray;help.FontSize=11;help.Margin=new Thickness(12);help.VerticalAlignment=VerticalAlignment.Bottom;help.IsHitTestVisible=false;Root.Children.Add(help);
   Root.MouseDown+=(s,e)=>{if(e.ChangedButton!=MouseButton.Left&&e.ChangedButton!=MouseButton.Middle)return;Root.Focus();if(e.ClickCount==2&&!MoveParts){Fit();e.Handled=true;return;}previous=start=e.GetPosition(Root);dragging=true;panning=e.ChangedButton==MouseButton.Middle||(Keyboard.Modifiers&ModifierKeys.Shift)!=0;if(MoveParts&&!panning){Pick(start);BeginPartDrag(selected,start);}Root.CaptureMouse();Root.Cursor=panning||movingPart!=null?Cursors.SizeAll:Cursors.Hand;e.Handled=true;};
