   Root.MouseUp+=(s,e)=>{if(!dragging)return;var end=e.GetPosition(Root);bool click=!panning&&movingPart==null&&(end-start).Length<4;EndPartDrag(false);dragging=false;Root.ReleaseMouseCapture();Root.Cursor=Cursors.Arrow;if(click)Pick(end);e.Handled=true;};Root.LostMouseCapture+=(s,e)=>{EndPartDrag(false);dragging=false;Root.Cursor=Cursors.Arrow;};
