  void Lights(){models.Children.Clear();models.Children.Add(new AmbientLight(Color.FromRgb(110,110,110)));models.Children.Add(new DirectionalLight(Color.FromRgb(180,180,180),new Vector3D(-.3,.5,-1)));models.Children.Add(new DirectionalLight(Color.FromRgb(90,90,90),new Vector3D(.7,-.3,.2)));}
  Material GetMaterial(System.Drawing.Color c){int key=c.ToArgb();Material m;if(materials.TryGetValue(key,out m))return m;var b=new SolidColorBrush(Color.FromRgb(c.R,c.G,c.B));b.Freeze();m=new DiffuseMaterial(b);m.Freeze();materials[key]=m;return m;}
  public void SetResult(Result result,bool asynchronous){if(ReferenceEquals(Result==null?null:Result.Model,result==null?null:result.Model)){Result=result;return;}EndPartDrag(false);offsets.Clear();selected=null;Result=result;NotifyPlacement();int ticket=++generation;if(cancellation!=null)cancellation.Cancel();cancellation=new CancellationTokenSource();var token=cancellation.Token;Ready=false;Error=null;Nodes.Clear();Lights();status.Text="Подготовка 3D-сборки…";
   if(result==null||result.Model==null||!result.Model.Valid){status.Text="3D-сборка недоступна. "+(result!=null&&result.Model!=null?string.Join(";",result.Model.Errors):"Рассчитайте передачу.");return;}
   var input=result;Action<List<SceneNode>,double> complete=(nodes,ms)=>{if(disposed||ticket!=generation)return;Nodes=nodes;BuildMilliseconds=ms;TriangleCount=Nodes.Sum(n=>n.Source.Triangles);MeshBuildCount=nodes.Count;foreach(var node in Nodes){node.Group=new Model3DGroup();node.Surface=new GeometryModel3D();node.Cap=new GeometryModel3D();node.Mark=new GeometryModel3D();node.Transform=new MatrixTransform3D();node.Material=GetMaterial(node.Part.Color);node.Surface.Material=node.Material;node.Surface.Geometry=node.Frozen;node.Mark.Geometry=ShowMarkers?node.MarkerFrozen:null;node.Mark.Material=GetMaterial(System.Drawing.Color.FromArgb(248,192,68));node.Cap.Material=GetMaterial(System.Drawing.Color.FromArgb(232,150,53));node.Group.Children.Add(node.Surface);node.Group.Children.Add(node.Cap);node.Group.Children.Add(node.Mark);node.Group.Transform=node.Transform;}belt.Build(input,GetMaterial(System.Drawing.Color.FromArgb(248,192,68)));Ready=true;RefreshVisibility();UpdatePose(Phase,true);Fit();fitPending=Root.ActualWidth<2;status.Text="";Select(selected);NotifyPlacement();if(Loaded!=null)Loaded();};
   if(!asynchronous){var watch=Stopwatch.StartNew();var nodes=BuildNodes(input,token);complete(nodes,watch.Elapsed.TotalMilliseconds);return;}
   Task.Factory.StartNew(()=>{var watch=Stopwatch.StartNew();var nodes=BuildNodes(input,token);return new Tuple<List<SceneNode>,double>(nodes,watch.Elapsed.TotalMilliseconds);},token).ContinueWith(task=>{if(disposed||ticket!=generation)return;Root.Dispatcher.BeginInvoke(new Action(()=>{if(disposed||ticket!=generation)return;if(task.IsCanceled)return;if(task.IsFaulted){Error=task.Exception.GetBaseException().Message;status.Text="Не удалось подготовить 3D: "+Error;return;}complete(task.Result.Item1,task.Result.Item2);}));});
  }
  static List<SceneNode> BuildNodes(Result result,CancellationToken token){lock(buildLock){token.ThrowIfCancellationRequested();var list=new List<SceneNode>();int index=0;foreach(var part in result.Model.Parts){token.ThrowIfCancellationRequested();var mesh=SceneMesher.Build(part,token);var node=new SceneNode{Part=part,Source=mesh,Frozen=mesh.Geometry(),Motion=PartMotion.Bind(result,part),Index=index++};if(part.Role=="shaft")node.Marker=MakeMarker(part);else if(result.P.CycloidLayout==1&&part.Id.EndsWith("_CASE_WALL"))node.Marker=CaseMarker(part);if(node.Marker!=null)node.MarkerFrozen=node.Marker.Geometry();list.Add(node);}return list;}}
  static SceneMesh CaseMarker(CadPart part){var s=part.Sections[0];if(!s.Outer.Circle)return null;double r=s.Outer.R+.03,a=-Math.PI/4-.035,b=a+.07,lo=part.Sections.Min(q=>q.Bottom),hi=part.Sections.Max(q=>q.Top),z0=lo+(hi-lo)*.2,z1=lo+(hi-lo)*.8;return new SceneMesh{Points=new[]{new Point3D(r*Math.Cos(a),r*Math.Sin(a),z0),new Point3D(r*Math.Cos(b),r*Math.Sin(b),z0),new Point3D(r*Math.Cos(b),r*Math.Sin(b),z1),new Point3D(r*Math.Cos(a),r*Math.Sin(a),z1)},Normals=new[]{new Vector3D(Math.Cos(a),Math.Sin(a),0),new Vector3D(Math.Cos(b),Math.Sin(b),0),new Vector3D(Math.Cos(b),Math.Sin(b),0),new Vector3D(Math.Cos(a),Math.Sin(a),0)},Indices=new[]{0,1,2,0,2,3}};}
  static SceneMesh MakeMarker(CadPart part){var section=part.Sections.Last();if(!section.Outer.Circle||section.Outer.R<.1)return null;var l=section.Outer;double z=section.Top+.025,r=l.R*.85,inner=section.Holes.Where(h=>h.Circle&&Math.Abs(h.X-l.X)<1e-5&&Math.Abs(h.Y-l.Y)<1e-5).Select(h=>h.R).DefaultIfEmpty(0).Max();if(inner>=r)r=l.R*.97;if(inner>=r)return null;Point3D[] points;if(inner>0){inner+=Math.Min(.03,(r-inner)/4);points=new[]{new Point3D(l.X+inner,l.Y,z),new Point3D(l.X+r,l.Y,z),new Point3D(l.X+r*Math.Cos(.45),l.Y+r*Math.Sin(.45),z),new Point3D(l.X+inner*Math.Cos(.45),l.Y+inner*Math.Sin(.45),z)};}else points=new[]{new Point3D(l.X,l.Y,z),new Point3D(l.X+r,l.Y,z),new Point3D(l.X+r*Math.Cos(.45),l.Y+r*Math.Sin(.45),z)};return new SceneMesh{Points=points,Normals=Enumerable.Repeat(new Vector3D(0,0,1),points.Length).ToArray(),Indices=points.Length==4?new[]{0,1,2,0,2,3}:new[]{0,1,2}};}

  public bool Visible(SceneNode n){return !Hidden.Contains(n.Part.Id)&&!(HideHousing&&n.Part.Role=="housing");}
  public void RefreshVisibility(){if(!Ready)return;Lights();foreach(var node in Nodes){bool visible=Visible(node);if(visible!=node.InScene)node.DisplayDirty=true;node.InScene=visible;if(visible)models.Children.Add(node.Group);}if(Axis<0&&belt.PartId!=null&&!Hidden.Contains(belt.PartId))models.Children.Add(belt.Group);UpdatePose(Phase);}
  public void Select(string id){selected=id;foreach(var node in Nodes)node.Surface.Material=node.Part.Id==selected?GetMaterial(System.Drawing.Color.FromArgb(246,189,70)):node.Material;NotifyPlacement();}
  public void UpdatePose(double phase,bool force=false){Phase=phase;if(!Ready)return;var watch=Stopwatch.StartNew();foreach(var node in Nodes){double explosion=Exploded?node.Index*2.5:0;var offset=Offset(node.Part.Id);Matrix3D pose=node.Motion.At(phase,explosion);pose.Translate(offset);bool changed=pose!=node.Pose;node.Pose=pose;if(!Visible(node)){node.DisplayDirty=true;continue;}bool refresh=force||node.DisplayDirty;node.DisplayDirty=false;
    if(Axis<0){if(refresh||node.HasClip||!ReferenceEquals(node.Surface.Geometry,node.Frozen)){node.Surface.Geometry=node.Frozen;node.Cap.Geometry=null;node.Mark.Geometry=ShowMarkers?node.MarkerFrozen:null;node.Mark.Transform=Transform3D.Identity;node.Group.Transform=node.Transform;node.HasClip=false;}if(changed||refresh)node.Transform.Matrix=pose;continue;}
    bool local=Axis==2;double coordinate=local?Coordinate-explosion-offset.Z:Coordinate;bool clipChanged=refresh||node.LastAxis!=Axis||node.LastCoordinate!=coordinate||node.LastPositive!=Positive||(!local&&pose!=node.LastClipPose);
    if(clipChanged){var transform=local?Matrix3D.Identity:pose;var result=MeshSection.Clip(node.Source,transform,Axis,coordinate,Positive,Math.Max(1e-7,Camera.Span*1e-8));node.Surface.Geometry=result.Body.Indices.Length>0?result.Body.Geometry():null;node.Cap.Geometry=result.Cap.Indices.Length>0?result.Cap.Geometry():null;if(node.Marker!=null&&ShowMarkers){var marker=MeshSection.Clip(node.Marker,transform,Axis,coordinate,Positive,Math.Max(1e-7,Camera.Span*1e-8));node.Mark.Geometry=marker.Body.Indices.Length>0?marker.Body.Geometry():null;}else node.Mark.Geometry=null;node.LastAxis=Axis;node.LastCoordinate=coordinate;node.LastPositive=Positive;node.LastClipPose=pose;node.HasClip=true;}
    node.Group.Transform=local?node.Transform:Transform3D.Identity;if(local&&(changed||refresh))node.Transform.Matrix=pose;
