  }
  public void ConfigureSection(int axis,double coordinate,bool positive){Axis=axis;Coordinate=coordinate;Positive=positive;RefreshVisibility();UpdatePose(Phase,true);}
  public void SetExploded(bool enabled){if(Exploded==enabled)return;Exploded=enabled;UpdatePose(Phase,true);Fit();}
  public Rect3D Bounds(bool visibleOnly){Rect3D bounds=Rect3D.Empty;if(!Ready)return bounds;foreach(var n in Nodes){if(visibleOnly&&!Visible(n))continue;var transformed=new MatrixTransform3D(n.Pose).TransformBounds(n.Frozen.Bounds);bounds.Union(transformed);}return bounds;}
  public void Fit(){var bounds=Bounds(true);if(bounds.IsEmpty)bounds=Bounds(false);Camera.Fit(bounds,Math.Max(.1,Root.ActualWidth/Math.Max(1,Root.ActualHeight)));}
  public void FocusPart(string id){var node=Nodes.FirstOrDefault(n=>n.Part.Id==id);if(node==null)return;Camera.Fit(new MatrixTransform3D(node.Pose).TransformBounds(node.Frozen.Bounds),Math.Max(.1,Root.ActualWidth/Math.Max(1,Root.ActualHeight)));}
  internal void Pick(Point point){if(!Ready)return;var origin=Camera.ScreenPoint(point.X,point.Y,Math.Max(1,Root.ActualWidth),Math.Max(1,Root.ActualHeight))+Camera.Direction*Math.Max(Camera.Span*3,10);double closest=double.MaxValue;string id=null;VisualTreeHelper.HitTest(visual,null,hit=>{var ray=hit as RayMeshGeometry3DHitTestResult;if(ray!=null&&ray.DistanceToRayOrigin<closest){var node=Nodes.FirstOrDefault(n=>ReferenceEquals(n.Surface,ray.ModelHit)||ReferenceEquals(n.Cap,ray.ModelHit)||ReferenceEquals(n.Mark,ray.ModelHit));if(node!=null){closest=ray.DistanceToRayOrigin;id=node.Part.Id;}}return HitTestResultBehavior.Continue;},new RayHitTestParameters(origin,-Camera.Direction));Select(id);if(Picked!=null)Picked(id);}
  public void SavePng(string file,int width,int height){Root.Measure(new Size(width,height));Root.Arrange(new Rect(0,0,width,height));Root.UpdateLayout();Camera.Update();var bitmap=new RenderTargetBitmap(width,height,96,96,PixelFormats.Pbgra32);bitmap.Render(Root);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var stream=File.Create(file))encoder.Save(stream);}
